function MetricCard({ title, value, detail, highlight }) {
  return (
    <div style={{ background: '#0f172a', border: '1px solid #1e293b', padding: '20px', borderRadius: '12px' }}>
      <p style={{ margin: '0 0 6px 0', color: '#94a3b8', fontSize: '12px' }}>{title}</p>
      <h2 style={{ margin: '0 0 6px 0', fontSize: '22px', color: highlight || '#fff', fontWeight: 'bold' }}>{value}</h2>
      <span style={{ color: '#64748b', fontSize: '11px' }}>{detail}</span>
    </div>
  );
}

const navBtnStyle = (active) => ({
  background: active ? '#1e293b' : 'transparent',
  color: active ? '#4ade80' : '#94a3b8',
  border: 'none',
  padding: '11px 14px',
  borderRadius: '8px',
  textAlign: 'left',
  cursor: 'pointer',
  display: 'flex',
  alignItems: 'center',
  gap: '10px',
  fontWeight: active ? '600' : 'normal',
  fontSize: '13px'
});

const thStyle = { padding: '14px 16px', fontSize: '12px', fontWeight: '600', color: '#94a3b8' };
const tdStyle = { padding: '14px 16px', fontSize: '14px', color: '#cbd5e1' };